result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/angles.test.mjs", "content": "import test from "node:test";
import assert from "node:assert";
import { clamp, normalizeDeg } from "./angles.mjs";

// ---- clamp ----
test("clamp middle", () => {
  assert.equal(clamp(5, 0, 10), 5);
});
test("clamp at lo boundary exactly", () => {
  assert.equal(clamp(0, 0, 10), 0);
});
test("clamp at hi boundary exactly", () => {
  assert.equal(clamp(10, 0, 10), 10);
});
test("clamp below lo", () => {
  assert.equal(clamp(-5, 0, 10), 0);
});
test("clamp above hi", () => {
  assert.equal(clamp(15, 0, 10), 10);
});

// ---- normalizeDeg ----
test("normalize positive wrap", () => {
  assert.equal(normalizeDeg(370), 10);
});
test("normalize deg spec values", () => {
  assert.equal(normalizeDeg(-30), 330);   // kills M5 (+= -> -=), M8 (+= 360 -> += 90)
  assert.equal(normalizeDeg(-360), 0);
  assert.equal(normalizeDeg(0), 0);
  assert.equal(normalizeDeg(360), 0);
  assert.equal(normalizeDeg(180), 180);   // kills M6 (% 360 -> % 180)
  assert.equal(normalizeDeg(539), 179);
});
"})
print(result)

result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/mutate.mjs", "content": "// Mutation testing harness for angles.mjs
//
// Original mutant list:
//   M1: x < lo   -> x <= lo     REMOVED: equivalent mutant. When x === lo, the
//       pristine code returns x, and x === lo, so "return lo" is
//       observationally identical. clamp's contract only exposes its return
//       value, so NO test can kill M1.
//   M2: return lo -> return hi  (first branch of clamp)
//   M3: x > hi   -> x >= hi     REMOVED: equivalent mutant. Symmetric to M1:
//       when x === hi the original returns x === hi; the mutant returns hi.
//       Indistinguishable from the outside.
//   M4: r < 0    -> r > 0       (normalizeDeg)
//   M5: r += 360 -> r -= 360    (normalizeDeg)
//   M6: a % 360  -> a % 180     (normalizeDeg)
//
// Replacement mutants (detectable, chosen to cover what M1/M3 pretended to):
//   M7: return x; -> return lo;  -- kills clamp's pass-through path; survives
//       any suite that never asserts an interior value like clamp(5,0,10)=5,
//       or one that only checks boundaries/clamping sides.
//   M8: r += 360 -> r += 90      -- wrong wrap amount for negative inputs;
//       survives suites that only test positive angles or multiples of 360.

import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const srcPath = path.join(here, "angles.mjs");
const testPath = path.join(here, "angles.test.mjs");

const src = fs.readFileSync(srcPath, "utf8");
const testSrc = fs.readFileSync(testPath, "utf8");

const MUTANTS = [
  { id: "M2", desc: 'clamp: "return lo" -> "return hi"', from: "return lo;", to: "return hi;" },
  { id: "M4", desc: 'normalizeDeg: "r < 0" -> "r > 0"', from: "if (r < 0)", to: "if (r > 0)" },
  { id: "M5", desc: 'normalizeDeg: "r += 360" -> "r -= 360"', from: "r += 360", to: "r -= 360" },
  { id: "M6", desc: 'normalizeDeg: "a % 360" -> "a % 180"', from: "a % 360", to: "a % 180" },
  { id: "M7", desc: 'clamp: pass-through "return x" -> "return lo"', from: "return x;", to: "return lo;" },
  { id: "M8", desc: 'normalizeDeg: "r += 360" -> "r += 90"', from: "r += 360", to: "r += 90" },
];

function count(haystack, needle) {
  let n = 0, i = 0;
  while ((i = haystack.indexOf(needle, i)) !== -1) { n++; i += needle.length; }
  return n;
}

function runNode(args, cwd) {
  try {
    const out = execFileSync(process.execPath, args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
    return { ok: true, out };
  } catch (e) {
    return { ok: false, out: `${e.stdout ?? ""}${e.stderr ?? ""}` };
  }
}

// ---------- 1. Pristine suite must pass ----------
const pristine = runNode(["--test", testPath], here);
if (!pristine.ok) {
  console.error("PRISTINE SUITE FAILED — fix tests before mutating.\n");
  console.error(pristine.out);
  process.exit(1);
}
console.log("Pristine suite: PASS\n");

// ---------- 2. Run each mutant ----------
const results = [];
const tmpBase = fs.mkdtempSync(path.join(os.tmpdir(), "mut-"));

for (const m of MUTANTS) {
  const occurrences = count(src, m.from);
  if (occurrences !== 1) {
    results.push({ ...m, status: "HARNESS-ERROR", detail: `"${m.from}" occurs ${occurrences}x in source` });
    continue;
  }

  const mutated = src.replace(m.from, m.to);
  if (mutated === src) {
    results.push({ ...m, status: "EQUIVALENT?", detail: "mutation produced identical source" });
    continue;
  }

  const dir = fs.mkdtempSync(path.join(tmpBase, `${m.id}-`));
  const modName = `angles.${m.id}.mjs`;
  const modFile = path.join(dir, modName);
  fs.writeFileSync(modFile, mutated);

  // Copy test file into temp dir, rewrite the import line at the mutant module.
  const rewritten = testSrc.replace(
    /from\s+"\.\/angles\.mjs"/,
    `from "./${modName}"`
  );
  if (rewritten === testSrc) {
    results.push({ ...m, status: "HARNESS-ERROR", detail: "could not rewrite import line" });
    continue;
  }
  const testFile = path.join(dir, "angles.test.mjs");
  fs.writeFileSync(testFile, rewritten);

  const run = runNode(["--test", "angles.test.mjs"], dir);
  // node --test exits non-zero iff at least one test failed => mutant killed.
  const killed = !run.ok;
  const failing = killed
    ? (run.out.match(/fail (\d+)/) ?? [])[1] ?? "?"
    : "0";
  results.push({
    ...m,
    status: killed ? "KILLED" : "SURVIVED",
    detail: killed ? `${failing} test(s) failed` : "all tests passed against mutant",
  });
  fs.rmSync(dir, { recursive: true, force: true });
}

fs.rmSync(tmpBase, { recursive: true, force: true });

// ---------- 3. Report ----------
console.log("Mutant".padEnd(6), "Mutation".padEnd(48), "Status".padEnd(10), "Detail");
console.log("-".repeat(100));
let killedCount = 0;
for (const r of results) {
  if (r.status === "KILLED") killedCount++;
  console.log(
    r.id.padEnd(6),
    r.desc.padEnd(48),
    r.status.padEnd(10),
    r.detail
  );
}
console.log("-".repeat(100));
console.log(`${killedCount}/${results.length} mutants killed`);

const allKilled = results.every((r) => r.status === "KILLED");
if (!allKilled) process.exit(1);
"})
print(result)

await bash('cd /tmp && rm -rf sanity && mkdir sanity && cd sanity && cp /workspace/angles.mjs . && cat > angles.test.mjs <<'EOF'
